@page "/settings"
@rendermode InteractiveServer
@using sv_51a5a26e993c4b8e92471eaa111eed0d.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <!-- Left sidebar navigation -->
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="settings-nav-item @(section == _activeSection ? "active" : "")"
                    @onclick="() => SetActiveSection(section)">
                    <span class="nav-icon">@GetSectionIcon(section)</span>
                    @section
                </li>
            }
        </ul>
    </nav>

    <!-- Main content area -->
    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (_toastVisible)
        {
            <div class="toast-notification @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastMessage
            </div>
        }
    </div>
</div>

<!-- Session revoke confirmation modal -->
@if (_showRevokeDialog)
{
    <div class="modal-backdrop fade show"></div>
    <div class="modal d-block fade show" tabindex="-1">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke?.Device</strong> from <strong>@_sessionToRevoke?.Location</strong>?</p>
                    <p class="text-muted mb-0">This will sign out the device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";
    private bool _loading = true;

    // Toast state
    private bool _toastVisible;
    private string _toastMessage = "";
    private bool _toastIsError;

    // Profile state
    private UserProfile? _profile;
    private UserProfile? _savedProfile;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editBio = "";
    private string _editAvatarUrl = "";

    // Notifications state
    private NotificationPrefs? _notificationPrefs;
    private bool _editEmailNotifications;
    private bool _editPushNotifications;
    private bool _editWeeklyDigest;
    private List<(string Channel, bool Muted)> _editChannels = new();

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _showRevokeDialog;
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private AppearanceSettings? _appearanceSettings;
    private string _editTheme = "Light";
    private string _editFontSize = "Medium";
    private string _editLanguage = "English";
    private bool _editCompactMode;

    private static readonly string[] AvailableLanguages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese", "Korean"];

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetActiveSection(string section)
    {
        _activeSection = section;
        _loading = true;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        switch (_activeSection)
        {
            case "Profile":
                _profile = await SettingsService.GetProfileAsync();
                _savedProfile = _profile;
                ResetProfileFields();
                break;
            case "Notifications":
                _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                ResetNotificationFields();
                break;
            case "Security":
                _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                _passwordPanelExpanded = false;
                _currentPassword = "";
                _newPassword = "";
                _confirmPassword = "";
                break;
            case "Appearance":
                _appearanceSettings = await SettingsService.GetAppearanceAsync();
                ResetAppearanceFields();
                break;
        }
        _loading = false;
    }

    private void ResetProfileFields()
    {
        if (_savedProfile is null) return;
        _editDisplayName = _savedProfile.DisplayName;
        _editEmail = _savedProfile.Email;
        _editBio = _savedProfile.Bio;
        _editAvatarUrl = _savedProfile.AvatarUrl;
    }

    private void ResetNotificationFields()
    {
        if (_notificationPrefs is null) return;
        _editEmailNotifications = _notificationPrefs.EmailNotifications;
        _editPushNotifications = _notificationPrefs.PushNotifications;
        _editWeeklyDigest = _notificationPrefs.WeeklyDigest;
        _editChannels = _notificationPrefs.MutedChannels
            .Select(ch => (ch, true))
            .ToList();
    }

    private void ResetAppearanceFields()
    {
        if (_appearanceSettings is null) return;
        _editTheme = _appearanceSettings.Theme;
        _editFontSize = _appearanceSettings.FontSize;
        _editLanguage = _appearanceSettings.Language;
        _editCompactMode = _appearanceSettings.CompactMode;
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        _profile = updated;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges() => ResetProfileFields();

    // Notification actions
    private void ToggleChannelMute(int index)
    {
        var (channel, muted) = _editChannels[index];
        _editChannels[index] = (channel, !muted);
    }

    private async Task SaveNotificationPrefs()
    {
        var mutedChannels = _editChannels.Where(c => c.Muted).Select(c => c.Channel).ToList();
        var updated = new NotificationPrefs(_editEmailNotifications, _editPushNotifications, _editWeeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notificationPrefs = updated;
        await ShowToast("Notification preferences saved!");
    }

    // Security actions
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword) ||
            string.IsNullOrWhiteSpace(_confirmPassword))
        {
            await ShowToast("Please fill in all password fields.", isError: true);
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", isError: true);
            return;
        }

        if (_newPassword.Length < 8)
        {
            await ShowToast("Password must be at least 8 characters.", isError: true);
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Password updated successfully!");
    }

    private void RequestRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeDialog = true;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
        _showRevokeDialog = false;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        }
        _showRevokeDialog = false;
        _sessionToRevoke = null;
        await ShowToast("Session revoked.");
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _appearanceSettings = updated;
        await ShowToast("Appearance settings saved!");
    }

    // Toast helper
    private async Task ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
        _toastVisible = true;
        StateHasChanged();
        await Task.Delay(3000);
        _toastVisible = false;
        StateHasChanged();
    }

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    private static string FormatRelativeTime(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    // Render fragments
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <h3 class="section-title">Profile</h3>
        <p class="section-description">Manage your personal information and public profile.</p>

        <div class="settings-card">
            <div class="avatar-section">
                <div class="avatar-preview">
                    @if (!string.IsNullOrWhiteSpace(_editAvatarUrl))
                    {
                        <img src="@_editAvatarUrl" alt="Avatar" class="avatar-img" />
                    }
                    else
                    {
                        <div class="avatar-placeholder">👤</div>
                    }
                </div>
                <div class="avatar-url-field">
                    <label class="form-label">Avatar URL</label>
                    <input type="text" class="form-control" @bind="_editAvatarUrl" placeholder="https://example.com/avatar.png" />
                </div>
            </div>

            <div class="mb-3">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-control" @bind="_editDisplayName" />
            </div>

            <div class="mb-3">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="_editEmail" />
            </div>

            <div class="mb-3">
                <label class="form-label">Bio</label>
                <textarea class="form-control" rows="3" @bind="_editBio"></textarea>
            </div>

            <div class="d-flex gap-2">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </div>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <h3 class="section-title">Notifications</h3>
        <p class="section-description">Control how and when you receive notifications.</p>

        <div class="settings-card">
            <h6 class="card-subtitle">General</h6>

            <div class="toggle-row">
                <div>
                    <div class="toggle-label">Email Notifications</div>
                    <div class="toggle-description">Receive notifications via email</div>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch" @bind="_editEmailNotifications" />
                </div>
            </div>

            <div class="toggle-row">
                <div>
                    <div class="toggle-label">Push Notifications</div>
                    <div class="toggle-description">Receive push notifications in your browser</div>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch" @bind="_editPushNotifications" />
                </div>
            </div>

            <div class="toggle-row">
                <div>
                    <div class="toggle-label">Weekly Digest</div>
                    <div class="toggle-description">Get a weekly summary of activity</div>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch" @bind="_editWeeklyDigest" />
                </div>
            </div>
        </div>

        <div class="settings-card mt-3">
            <h6 class="card-subtitle">Muted Channels</h6>
            <p class="text-muted small">Select channels to mute. Muted channels won't send notifications.</p>

            @for (var i = 0; i < _editChannels.Count; i++)
            {
                var index = i;
                var (channel, muted) = _editChannels[index];
                <div class="channel-row">
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" checked="@muted"
                               @onchange="() => ToggleChannelMute(index)" id="@($"ch-{index}")" />
                        <label class="form-check-label" for="@($"ch-{index}")">
                            <span class="channel-name">#@channel</span>
                        </label>
                    </div>
                    <span class="badge @(muted ? "bg-secondary" : "bg-success")">
                        @(muted ? "Muted" : "Active")
                    </span>
                </div>
            }

            <div class="mt-3">
                <button class="btn btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
            </div>
        </div>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <h3 class="section-title">Security</h3>
        <p class="section-description">Manage your account security and active sessions.</p>

        <!-- Change Password -->
        <div class="settings-card">
            <div class="expandable-header" @onclick="() => _passwordPanelExpanded = !_passwordPanelExpanded">
                <h6 class="card-subtitle mb-0">Change Password</h6>
                <span class="expand-icon">@(_passwordPanelExpanded ? "▲" : "▼")</span>
            </div>

            @if (_passwordPanelExpanded)
            {
                <div class="expandable-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>

                    @if (_securitySettings?.LastPasswordChange is not null)
                    {
                        <p class="text-muted small">Last changed: @_securitySettings.LastPasswordChange.Value.ToString("MMM dd, yyyy")</p>
                    }

                    <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="settings-card mt-3">
            <div class="toggle-row">
                <div>
                    <div class="toggle-label">Two-Factor Authentication</div>
                    <div class="toggle-description">
                        Add an extra layer of security to your account
                    </div>
                </div>
                <div class="d-flex align-items-center gap-2">
                    <span class="badge @(_securitySettings?.TwoFactorEnabled == true ? "bg-success" : "bg-warning text-dark")">
                        @(_securitySettings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")
                    </span>
                    <div class="form-check form-switch mb-0">
                        <input class="form-check-input" type="checkbox" role="switch"
                               checked="@(_securitySettings?.TwoFactorEnabled ?? false)" disabled />
                    </div>
                </div>
            </div>
        </div>

        <!-- Active Sessions -->
        <div class="settings-card mt-3">
            <h6 class="card-subtitle">Active Sessions</h6>
            <p class="text-muted small">Devices currently signed in to your account.</p>

            <div class="table-responsive">
                <table class="table table-hover mb-0">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (_securitySettings?.Sessions is not null)
                        {
                            var isFirst = true;
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                var isCurrent = isFirst;
                                <tr>
                                    <td>
                                        @session.Device
                                        @if (isCurrent)
                                        {
                                            <span class="badge bg-primary ms-1">Current</span>
                                        }
                                    </td>
                                    <td>@session.Location</td>
                                    <td>@FormatRelativeTime(session.LastActive)</td>
                                    <td>
                                        @if (!isCurrent)
                                        {
                                            <button class="btn btn-outline-danger btn-sm"
                                                    @onclick="() => RequestRevoke(session)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                                isFirst = false;
                            }
                        }
                    </tbody>
                </table>
            </div>
        </div>
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <h3 class="section-title">Appearance</h3>
        <p class="section-description">Customize how the application looks and feels.</p>

        <div class="settings-card">
            <!-- Theme -->
            <div class="mb-4">
                <h6 class="card-subtitle">Theme</h6>
                <div class="d-flex gap-3">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        var t = theme;
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="@($"theme-{t}")" value="@t"
                                   checked="@(_editTheme == t)"
                                   @onchange="() => _editTheme = t" />
                            <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                        </div>
                    }
                </div>
            </div>

            <!-- Font Size -->
            <div class="mb-4">
                <h6 class="card-subtitle">Font Size</h6>
                <div class="d-flex gap-3">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        var s = size;
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="@($"fs-{s}")" value="@s"
                                   checked="@(_editFontSize == s)"
                                   @onchange="() => _editFontSize = s" />
                            <label class="form-check-label" for="@($"fs-{s}")">@s</label>
                        </div>
                    }
                </div>
            </div>

            <!-- Language -->
            <div class="mb-4">
                <h6 class="card-subtitle">Language</h6>
                <select class="form-select" style="max-width: 300px;" @bind="_editLanguage">
                    @foreach (var lang in AvailableLanguages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="mb-4">
                <div class="toggle-row">
                    <div>
                        <div class="toggle-label">Compact Mode</div>
                        <div class="toggle-description">Reduce spacing and padding throughout the UI</div>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" role="switch" @bind="_editCompactMode" />
                    </div>
                </div>
            </div>
        </div>

        <!-- Live Preview -->
        <div class="settings-card mt-3">
            <h6 class="card-subtitle">Preview</h6>
            <div class="preview-area @GetPreviewThemeClass()" style="@GetPreviewStyle()">
                <div class="preview-header">
                    <strong>Dashboard</strong>
